import { AxisScale } from '@visx/axis';
import React, { forwardRef, ReactNode } from 'react';

import { AnnotationsContent } from './components/AnnotationsContent.js';
import { AnnotationsProviders } from './providers/AnnotationsProviders.js';
import { Annotation } from './types/annotations.js';
import { SelectionState } from './types/state.js';
import { AnnotationsActionsTemplate } from './types/tooltip.js';
import { TrackProps } from './types/tracks.js';

/**
 * @internal
 */
export interface AnnotationsTimeseriesRendererProps {
  scale: AxisScale<number>;
  width: number;
  height?: number;
  tracks: TrackProps[];
  labelsOffset: number;
  markerGroupHover?: (event: Partial<SelectionState>) => void;
  showLabels?: boolean;
  annotationsActions?: (annotation: Annotation) => ReactNode;
}

export const AnnotationsTimeseriesRenderer = /* @__PURE__ */ forwardRef<
  SVGSVGElement,
  AnnotationsTimeseriesRendererProps
>(
  (
    {
      showLabels,
      scale,
      width,
      height,
      tracks,
      annotationsActions,
      markerGroupHover,
      labelsOffset,
    },
    forwardedRef,
  ) => (
    <AnnotationsProviders
      scale={scale}
      onAnnotationsMarkersInteraction={markerGroupHover}
      tracks={tracks}
      annotationsActions={annotationsActions as AnnotationsActionsTemplate}
      showLabels={showLabels}
    >
      <AnnotationsContent
        width={width}
        height={height}
        labelsOffset={labelsOffset}
        ref={forwardedRef}
      />
    </AnnotationsProviders>
  ),
);

AnnotationsTimeseriesRenderer['displayName'] = 'AnnotationsTimeseriesRenderer';
